    col *= 1.0 - 0.9*smoothstep(0.55, 0.95, s);                               // \u592A\u967D\u306E\u5468\u308A\u306F\u6697\u304F\u629C\u3044\u3066\u4E3B\u5F79\u3092\u7ACB\u3066\u308B
